def transform2(g):
    from collections import defaultdict
    cells=defaultdict(list)
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v: cells[v].append((r,c))
    sp={}
    for v,pts in cells.items():
        rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
        r0,c0=min(rs),min(cs)
        m=[[0]*(max(cs)-c0+1) for _ in range(max(rs)-r0+1)]
        for r,c in pts: m[r-r0][c-c0]=v
        sp[v]=(c0,m)
    H=max(len(m) for _,m in sp.values())
    cols=[]
    for v,c0 in sorted((c0,v) for v,(c0,m) in sp.items()):
        m=sp[v][1]
        for c in zip(*m):
            cols.append(list(c)+[0]*(H-len(c)))
    return [list(row) for row in zip(*cols)]
